import sys, json, time, platform, math, random
from pathlib import Path

START = time.time()
sys.path.append('storage/shared')

# Seeding utilities (package or shim fallback)
seed_tools_ok = True
try:
    from utilities.seed_tools import set_seed, make_rng, seed_from_str, mix_seed
except Exception:
    seed_tools_ok = False
    try:
        from seed_tools import set_seed, make_rng, seed_from_str, mix_seed  # shim
    except Exception:
        import random as _r, hashlib as _h
        def _u32(x): return int(x) & 0xFFFFFFFF
        def set_seed(s): _r.seed(_u32(s)); return _u32(s)
        def make_rng(s): set_seed(s); return None, _r.Random(_u32(s))
        def seed_from_str(s): return int(_h.sha256(s.encode()).hexdigest()[:8], 16)
        def mix_seed(a,b): return (_u32(a) ^ (_u32(b) + 0x9E3779B9)) & 0xFFFFFFFF

from coord.bidirectional_ring import simulate_bidir_broadcast
from coord.metrics import basic_metrics

base_seed = seed_from_str("Axiom-bidir-ring-v0")
set_seed(base_seed)
_, _ = make_rng(base_seed)

def expected_steps_bidir(N: int) -> int:
    return math.ceil((N - 1) / 2)

cfg = {
    "Ns": [24, 25],
    "max_steps": 400,
    "stochastic_p": 0.6,
    "replicates": 10
}

cases = []
# Deterministic checks
for N in cfg["Ns"]:
    det = simulate_bidir_broadcast(N=N, p_send=1.0, max_steps=cfg["max_steps"])
    det_met = basic_metrics(det)
    exp_steps = expected_steps_bidir(N)
    cases.append({
        "label": f"deterministic_N{N}",
        "N": N,
        "p_send": 1.0,
        "expected_steps_to_full": exp_steps,
        "result": det,
        "metrics": det_met,
        "matches_expectation": (det_met.get("time_to_full") == exp_steps),
    })

# Stochastic runs (fixed N)
N_sto = cfg["Ns"][1]
p_sto = cfg["stochastic_p"]
runs = []
for r in range(cfg["replicates"]):
    run_seed = mix_seed(base_seed, r + 1)
    rng = random.Random(run_seed)
    res = simulate_bidir_broadcast(N=N_sto, p_send=p_sto, max_steps=cfg["max_steps"], rng=rng)
    met = basic_metrics(res)
    runs.append({"seed": run_seed, "result": res, "metrics": met})

# Aggregate stochastic metrics
import statistics as stats
def _vals(key):
    v = [x["metrics"].get(key) for x in runs]
    return [x for x in v if x is not None]

agg = {}
for key in ["coverage", "time_to_full", "throughput_msgs_per_step"]:
    v = _vals(key)
    if v:
        try:
            agg[key] = {"count": len(v), "mean": float(stats.fmean(v)), "min": float(min(v)), "max": float(max(v))}
        except Exception:
            v2 = [x for x in v if x is not None]
            agg[key] = {"count": len(v2), "mean": float(stats.fmean(v2)) if v2 else None, "min": float(min(v2)) if v2 else None, "max": float(max(v2)) if v2 else None}
    else:
        agg[key] = {"count": 0}

out_dir = Path("storage/shared/coord/results")
out_dir.mkdir(parents=True, exist_ok=True)
out_path = out_dir / "axiom_bidir_baseline_v0.json"

report = {
    "env": {
        "python": platform.python_version(),
        "implementation": platform.python_implementation(),
        "platform": platform.platform(),
        "seed_tools_imported": seed_tools_ok,
    },
    "config": cfg,
    "deterministic_cases": cases,
    "stochastic_runs": runs,
    "aggregate": agg,
}

with open(out_path, "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, sort_keys=True)

END = time.time()
# Print compact summary
det_summary = {c["N"]: {"observed": c["metrics"].get("time_to_full"), "expected": c["expected_steps_to_full"], "ok": c["matches_expectation"]} for c in cases}
print("=== Bidirectional Ring Baseline v0 ===")
print(json.dumps({
    "artifact": str(out_path),
    "deterministic_checks": det_summary,
    "stochastic_N": N_sto,
    "stochastic_p": p_sto,
    "stochastic_time_to_full_mean": report["aggregate"]["time_to_full"].get("mean"),
    "stochastic_coverage_mean": report["aggregate"]["coverage"].get("mean"),
    "timing_sec": round(END - START, 6),
}, indent=2))
print("Bidirectional baseline complete.")

